SELECT DATE_TRUNC('QUARTER', sale_date) AS quarter_start, product_id, AVG(revenue) AS avg_revenue, COUNT(*) AS event_count, ROUND(AVG(units), 2) AS avg_units, PERCENTILE_APPROX(revenue, 0.5) AS revenue_p50, MIN(units) AS min_units, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', sale_date) ORDER BY PERCENTILE_APPROX(revenue, 0.5) DESC) AS revenue_p50_dense_rank FROM store_sales GROUP BY DATE_TRUNC('QUARTER', sale_date), product_id HAVING event_count > 1
